const input = $('Set — Normalize Trade Input').item.json;
const hs = $('HTTP — HS Classifier').item.json;
const forecast = $('HTTP — XGBoost Demand Forecaster').item.json;
const anomaly = $('HTTP — IsolationForest Anomaly Engine').item.json;
const compliance = $('HTTP — Compliance RAG Retriever').item.json;
const counterparties = $('HTTP — Counterparty Match & Sanctions').item.json;
const dossier = $('HTTP — Multi-Model Report Synthesizer').item.json;

return [{
  json: {
    status: 'SUCCESS',
    execution_id: 'n8n_exec_' + Date.now(),
    trade_flow: input.trade_flow,
    input_summary: input,
    hs_classification: hs,
    demand_forecasting: {
      engine: 'XGBoost Residual Forecaster (Q10/50/90)',
      recommendations: forecast.top_recommendations || []
    },
    trade_anomaly: anomaly,
    compliance_rag: {
      status: compliance.status,
      compliance_score: compliance.compliance_score,
      tariff: compliance.tariff,
      ntm_barriers: compliance.ntm_barriers || [],
      required_documents: compliance.required_documents || [],
      retrieved_evidence: compliance.retrieved_evidence || [],
      sources_cited: compliance.sources_cited || []
    },
    counterparties: counterparties.counterparties || [],
    executive_dossier: dossier,
    models_executed: [
      'HS Code Neural Classifier',
      'XGBoost Quantile Residual Demand Forecaster',
      'TreeSHAP Economic Attribution Engine',
      'Unsupervised IsolationForest Anomaly Engine',
      '26-Year Peer-Price Z-Score Distribution',
      'Multi-Dataset TF-IDF Compliance & Tariff RAG',
      'OFAC/UN/UK/EU 31k Entity Sanctions Screener',
      'Deterministic Trade Report Synthesizer'
    ],
    executed_at: new Date().toISOString()
  }
}];
